+import { project } from "./project.ts";
+import { recordsForPath } from "./query.ts";
+
+interface BootstrapOptions {
+  repo: string;
+  paths: string[];
+}
+
+export const bootstrapRecords = (opts: BootstrapOptions): string | null => {
+  const allRecords = opts.paths
+    .flatMap(path => recordsForPath(opts.repo, path))
+    .reduce((acc, record) => {
+      const key = `${record.file}:${record.line}`;
+      if (!acc.has(key)) acc.set(key, record);
+      return acc;
+    }, new Map());
+
+  if (allRecords.size === 0) return null;
+
+  return project(Array.from(allRecords.values()));
+};
+
+export const bootstrapForRepo = (repo: string): string | null => {
+  const sourcePaths = [
+    "src/",
+    "lib/",
+    "components/",
+    "utils/",
+  ];
+  return bootstrapRecords({ repo, paths: sourcePaths });
+};
